tasks.solution:
public static void rotateRight(int[] arr) {
    int last = arr[arr.length - 1];
    for (int i = arr.length - 1; i > 0; i--) {
        arr[i] = arr[i - 1];
    }
    arr[0] = last;
}

public static int longestRun(int[] arr) {
    int best = 1;
    int run = 1;
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] == arr[i - 1]) {
            run++;
        } else {
            run = 1;
        }
        if (run > best) {
            best = run;
        }
    }
    return best;
}

