int[] arr = { 4, 7, 1, 9 };
rotateRight(arr);
System.out.println("סעיף א, בדיקה 1: " + check(arr, "[9, 4, 7, 1]"));
rotateRight(arr);
System.out.println("סעיף א, בדיקה 2: " + check(arr, "[1, 9, 4, 7]"));
int[] one = { 6 };
rotateRight(one);
System.out.println("סעיף א, בדיקה 3: " + check(one, "[6]"));
System.out.println("סעיף ב, בדיקה 1: " + check(longestRun(new int[] { 5, 5, 2, 2, 2, 8, 2 }), 3));
System.out.println("סעיף ב, בדיקה 2: " + check(longestRun(new int[] { 6 }), 1));
System.out.println("סעיף ב, בדיקה 3: " + check(longestRun(new int[] { 3, 3, 3, 3 }), 4));

